var sidebar = new Border
{
    Width = 272,
    Padding = new Thickness(10),
    Child = new StackPanel
    {
        Spacing = 2,
        Children =
        {
            AppKit.Pressable(WorkspaceHeader(current), () => switcherOpen = !switcherOpen),
            AppKit.Search("Search", text => { query = text; Build(); }, 216, query, "["),
            SectionLabel("Favorites", favorites.Count),
            favorites.Select(item => NavRow(item)).ToStack(),
            SectionLabel("Projects", projects.Count),
            projects.Select(item => NavRow(item)).ToStack(),
            AppKit.RailIcon("panel-left", "Collapse the sidebar", () => collapsed = true)
        }
    }
};

var shell = new Grid { ColumnDefinitions = new ColumnDefinitions("272,*") };
shell.Children.Add(sidebar);
shell.Children.Add(AppKit.Place(contentHost, 1));
return AppKit.Screen(shell, 580);
